// R1-T3 authored props (D-057): builds the per-hood street kit as SVG.
// Writes art/arenas/props/<theme>-<kind>-<variant>.svg (review copies), js/view/arena-props-data.js (what the game loads; SVG as strings,
// so it works from file://) and js/strings-signs.js (sign words, from the label texts). Sources: tools/arena-props/<theme>.js for the
// bespoke hoods, tools/arena-props/hoods.js for the rest; builders in kit-*.js, helpers in lib.js.
// Usage: node prototype/tools/gen-arena-props.js
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const BESPOKE = ['istiklal', 'bazaar', 'atakoy'];

const kits = {};
BESPOKE.forEach(id => { kits[id] = require(path.join(__dirname, 'arena-props', id + '.js')); });
Object.assign(kits, require(path.join(__dirname, 'arena-props', 'hoods.js')));

const dir = path.join(ROOT, 'art', 'arenas', 'props'); fs.mkdirSync(dir, { recursive: true });
fs.readdirSync(dir).filter(n => n.endsWith('.svg')).forEach(n => fs.unlinkSync(path.join(dir, n)));
const data = {}, report = [], words = {};
Object.keys(kits).forEach(id => {
  data[id] = {};
  Object.keys(kits[id]).forEach(kind => {
    data[id][kind] = kits[id][kind].map((p, v) => {
      fs.writeFileSync(path.join(dir, id + '-' + kind + '-' + v + '.svg'), p.svg);
      if (p.label) words[p.label.key] = p.label.text;
      return { w: p.w, h: p.h, ax: p.ax, ay: p.ay, fw: p.fw, fd: p.fd, svg: p.svg, label: p.label ? { key: p.label.key, col: p.label.col, x: p.label.x, y: p.label.y, w: p.label.w, h: p.label.h } : null };
    });
  });
  report.push(id + '[' + Object.keys(kits[id]).length + ']');
});
const out = '// GENERATED by tools/gen-arena-props.js (R1-T3, D-057). Do not edit by hand. Source: art/arenas/props/*.svg.\n' +
  'P.ArenaPropsData = ' + JSON.stringify(data) + ';\n';
fs.writeFileSync(path.join(ROOT, 'prototype', 'js', 'view', 'arena-props-data.js'), out);

const rows = Object.keys(words).sort().map(k => "'" + k + "': '" + words[k] + "'").join(', ');
const strings = '// GENERATED by tools/gen-arena-props.js (R1-T3). Do not edit by hand: change the label text in tools/arena-props/*.js.\n' +
  '// Sign words on authored street props. Keys: sign.* (written at runtime by view/arena-props.js, so the art holds no words).\n' +
  '// Shop and vendor names are proper nouns from docs/hood-visual-briefs.md; each carries "TR owner check" until the owner confirms.\n' +
  'Object.assign(P.STR.tr, {\n  ' + rows + ',\n});\nObject.assign(P.STR.en, {\n  ' + rows + ',\n});\n';
fs.writeFileSync(path.join(ROOT, 'prototype', 'js', 'strings-signs.js'), strings);
console.log('arena props: ' + report.join(' ') + ', ' + (out.length / 1024).toFixed(0) + ' KB, ' + Object.keys(words).length + ' sign words');
